import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';

/**
 * Consumer-boundary proof for Workshop maintenance. The fixture pack is generated by
 * workshop.publish.py through its real validator, then handed to the existing engine
 * registration path. No checked-in pack or learning-state file is read or written.
 */

const REPOSITORY_ROOT = path.resolve(import.meta.dirname, '../..');
const NOW = Date.UTC(2026, 8, 7);

const PYTHON_FIXTURE = String.raw`
import hashlib
import json
from pathlib import Path
import sys

from workshop.publish import publish
from workshop.store import Workshop

root = Path(sys.argv[1]).resolve()
temporary = Path(sys.argv[2]).resolve()
source_path = temporary / "neutral-source.txt"
text = "The copper bridge opens at dawn.\nThe copper bridge opens at noon.\n"
source_path.write_text(text)
prepared = {
    "uri": str(source_path),
    "title": "Neutral Reference",
    "kind": "document",
    "source_ref": "chapter-neutral",
    "as_of": "2026-08-31",
    "attribution": {"creator": "Fixture Author", "layer_id": "fixture"},
    "authority": {"level": "secondary", "label": "Neutral fixture"},
    "text": text,
    "node_id": "node.neutral",
    "locator": {"section": "Chapter Neutral"},
    "currency": {"status": "verified", "note": "fixture edition checked"},
    "crate_eligible": True,
    "original_sha256": hashlib.sha256(text.encode()).hexdigest(),
    "derivation": {"method": "neutral consumer fixture"},
}
workshop = Workshop(root, temporary / "workshop-data")
imported = workshop.import_prepared(prepared)
job = workshop.run_job(imported["job"]["id"], lambda *_: [
    {"statement": "The bridge opens at dawn.", "quote": "The copper bridge opens at dawn."},
    {"statement": "The bridge opens at noon.", "quote": "The copper bridge opens at noon."},
])
snapshot = workshop.snapshot()
old, new = [next(p for p in snapshot["propositions"] if p["id"] == pid) for pid in job["accepted_outputs"]]
workshop.review_proposition(old["id"], "approved", "fixture-reviewer", "original checked", method="human")
base = next(iter(sorted((root / "packs").glob("*/pack.json"))))
publish(workshop, "fixture-publisher", base)
workshop.review_proposition(new["id"], "approved", "fixture-reviewer", "replacement checked", method="human")
workshop.add_relation(new["id"], old["id"], "supersedes", "confirmed", "replacement confirmed", "fixture-reviewer")
result = publish(workshop, "fixture-publisher", base)
print(json.dumps({
    "pack_path": str(Path(result["publication"]["directory"]) / "pack.json"),
    "old_id": "workshop." + old["id"],
    "new_id": "workshop." + new["id"],
}))
`;

type GeneratedFixture = { pack_path: string; old_id: string; new_id: string };
type PackEnvelope = { meta: { id: string }; facts: Array<{ id: string }> };

let temporary = '';
let generated: GeneratedFixture;
let pack: PackEnvelope;
let disk = new Map<string, unknown>();

beforeAll(() => {
  temporary = fs.mkdtempSync(path.join(os.tmpdir(), 'fw-workshop-consumer-'));
  generated = JSON.parse(
    execFileSync('python3', ['-c', PYTHON_FIXTURE, REPOSITORY_ROOT, temporary], {
      cwd: REPOSITORY_ROOT,
      encoding: 'utf8',
    }),
  ) as GeneratedFixture;
  pack = JSON.parse(fs.readFileSync(generated.pack_path, 'utf8')) as PackEnvelope;
});

afterAll(() => {
  fs.rmSync(temporary, { recursive: true, force: true });
});

function stubFetch() {
  vi.stubGlobal(
    'fetch',
    vi.fn(async (url: unknown, init?: { method?: string; body?: string }) => {
      const target = String(url);
      if (target.includes('/api/packs')) {
        return { ok: true, json: async () => ({ packs: [{ id: pack.meta.id, dir: 'generated', pack }] }) };
      }
      const name = target.replace('/api/state/', '');
      if (init?.method === 'PUT') {
        disk.set(name, JSON.parse(init.body ?? 'null'));
        return { ok: true, json: async () => ({ ok: true }) };
      }
      if (!disk.has(name)) return { ok: false, status: 404, json: async () => ({}) };
      return { ok: true, json: async () => disk.get(name) };
    }),
  );
}

async function boot() {
  vi.resetModules();
  const { services } = await import('../../app/src/game/contracts');
  await import('../../app/src/srs/register');
  await services.srs.ready();
  await services.amendments.ready();
  return services;
}

beforeEach(() => {
  disk = new Map();
  stubFetch();
});

afterEach(() => {
  vi.unstubAllGlobals();
});

describe('generated Workshop supersession pack consumed by the real engine', () => {
  it('retires old due history, gates a fresh successor, and never migrates the old record', async () => {
    const oldRecord = {
      box: 4,
      next_due: NOW - 1,
      history: [{ quality: 1, at: NOW - 10_000, encounter_id: 'old-encounter' }],
    };
    disk.set('srs.json', { version: 1, facts: { [generated.old_id]: oldRecord } });
    const services = await boot();

    expect(services.srs.dueQueue(pack.meta.id, [generated.old_id, generated.new_id], NOW)).toEqual([]);
    expect(services.srs.historyQualities(generated.old_id)).toEqual([1]);
    expect(services.srs.historyQualities(generated.new_id)).toEqual([]);
    expect(disk.get('srs.json')).toEqual({ version: 1, facts: { [generated.old_id]: oldRecord } });

    await services.amendments.witness(generated.old_id);
    expect(services.srs.dueQueue(pack.meta.id, [generated.old_id, generated.new_id], NOW)).toEqual([
      generated.new_id,
    ]);
    expect(services.srs.historyQualities(generated.old_id)).toEqual([1]);
    expect(services.srs.historyQualities(generated.new_id)).toEqual([]);
    expect(disk.get('srs.json')).toEqual({ version: 1, facts: { [generated.old_id]: oldRecord } });
  });

  it('always excludes a fresh old fact and admits an already-due successor after witness', async () => {
    const newRecord = {
      box: 2,
      next_due: NOW - 1,
      history: [{ quality: 0.5, at: NOW - 10_000, encounter_id: 'new-encounter' }],
    };
    disk.set('srs.json', { version: 1, facts: { [generated.new_id]: newRecord } });
    disk.set('amendments.json', { [generated.old_id]: '2026-09-07T00:00:00Z' });
    const services = await boot();

    expect(services.srs.dueQueue(pack.meta.id, [generated.old_id, generated.new_id], NOW)).toEqual([
      generated.new_id,
    ]);
    expect(services.srs.historyQualities(generated.old_id)).toEqual([]);
    expect(services.srs.historyQualities(generated.new_id)).toEqual([0.5]);
    expect(disk.get('srs.json')).toEqual({ version: 1, facts: { [generated.new_id]: newRecord } });
  });
});
